#!/usr/bin/env node

/**
 * Generate a coverage comment for a single test suite.
 * Usage: node generate-single-coverage-comment.js --suite <backend|client|legacy>
 */

const fs = require('fs');

const SUITES = {
  backend: {
    file: 'coverage/coverage-summary.json',
    title: '## 📊 Backend Coverage',
    emoji: '🔧',
    label: 'Worker (Backend)',
    tool: 'Jest',
  },
  client: {
    file: 'coverage/client/coverage-summary.json',
    title: '## 📊 Client Coverage',
    emoji: '⚛️',
    label: 'Client (Preact)',
    tool: 'Vitest',
  },
  legacy: {
    file: 'coverage/legacy/coverage-summary.json',
    title: '## 📊 Legacy UI Coverage',
    emoji: '🎨',
    label: 'UI (Legacy)',
    tool: 'Jest',
  },
};

// Parse --suite argument
const args = process.argv.slice(2);
const suiteIdx = args.indexOf('--suite');
if (suiteIdx === -1 || !args[suiteIdx + 1]) {
  console.error('Usage: node generate-single-coverage-comment.js --suite <backend|client|legacy>');
  process.exit(1);
}

const suiteName = args[suiteIdx + 1];
const suite = SUITES[suiteName];
if (!suite) {
  console.error(`Unknown suite: ${suiteName}. Must be one of: ${Object.keys(SUITES).join(', ')}`);
  process.exit(1);
}

// Read coverage data
let coverage = null;
try {
  if (fs.existsSync(suite.file)) {
    coverage = JSON.parse(fs.readFileSync(suite.file, 'utf8'));
  }
} catch (e) {
  console.error(`Error reading ${suite.file}:`, e.message);
}

// Build comment
let comment = `${suite.title}\n\n`;

if (coverage && coverage.total) {
  const t = coverage.total;
  const hasData = t.lines && t.lines.pct !== 'Unknown';

  if (hasData) {
    comment += `### ${suite.emoji} ${suite.label}\n\n`;
    comment += '| Metric | Coverage |\n';
    comment += '|--------|----------|\n';
    comment += `| **Lines** | ${t.lines?.pct ?? 'N/A'}% |\n`;
    comment += `| **Statements** | ${t.statements?.pct ?? 'N/A'}% |\n`;
    comment += `| **Functions** | ${t.functions?.pct ?? 'N/A'}% |\n`;
    comment += `| **Branches** | ${t.branches?.pct ?? 'N/A'}% |\n\n`;
  } else {
    comment += `### ${suite.emoji} ${suite.label}\n\n`;
    comment += '_No test coverage data collected_\n\n';
  }
} else {
  comment += `### ${suite.emoji} ${suite.label}\n\n`;
  comment += '_No coverage data available_\n\n';
}

comment += '---\n\n';
comment += `_Coverage report generated by ${suite.tool}_\n`;

// Write to file
fs.writeFileSync('coverage-comment.md', comment);
console.log(`✅ ${suiteName} coverage comment generated successfully`);
console.log('\nPreview:\n');
console.log(comment);
